Here's a C# code snippet to calculate the sum of the digits in the first 15 Fibonacci numbers:
using System;
class Program
{
    static int SumOfDigits(int n)
    {
        int sum = 0;
        while (n != 0)
        {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
    static void Main()
    {
        int[] fibonacci = new int[15];
        fibonacci[0] = 0;
        fibonacci[1] = 1;
        for (int i = 2; i < 15; i++)
        {
            fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
        }
        int sumOfDigitsOfFibonacci = 0;
        for (int i = 0; i < 15; i++)
        {
            sumOfDigitsOfFibonacci += SumOfDigits(fibonacci[i]);
        }
        Console.WriteLine($"The sum of the digits in the first 15 Fibonacci numbers is {sumOfDigitsOfFibonacci}.");
    }
}
