#include <iostream>
#include <fstream>
#include <string>
using namespace std;
int main() {
    string filename = "input.txt";
    string word = "example";
    string line;
    ifstream file(filename);
    if (file.is_open()) {
        while (getline(file, line)) {
            size_t pos = 0;
            while ((pos = line.find(word, pos)) != string::npos) {
                line.insert(pos, "\033[31m");
                pos += 7;
                line.insert(pos, "\033[0m");
                pos += 4;
            }
            cout << line << endl;
        }
        file.close();
    }
    return 0;
}
