Certainly! Here's some sample Swift code that loads the ResNet50 and VGG16 models, loads the images, runs the inference, and outputs the accuracy and speed results for each model:
```swift
import CoreML
import Vision
// Load the ResNet50 model
guard let resnetModel = try? VNCoreMLModel(for: Resnet50().model) else {
    fatalError("Failed to load ResNet50 model.")
}
// Load the VGG16 model
guard let vggModel = try? VNCoreMLModel(for: VGG16().model) else {
    fatalError("Failed to load VGG16 model.")
}
// Load the images
let imageUrls = ["path/to/image1.jpg", "path/to/image2.jpg", ..., "path/to/image1000.jpg"]
var images = [CGImage]()
for imageUrl in imageUrls {
    guard let image = UIImage(contentsOfFile: imageUrl)?.cgImage else {
        fatalError("Failed to load image at \(imageUrl).")
    }
    images.append(image)
}
// Run inference on the ResNet50 model
var resnetTotalTime: Double = 0
var resnetCorrectCount = 0
for image in images {
    let request = VNCoreMLRequest(model: resnetModel) { (request, error) in
        guard let results = request.results as? [VNClassificationObservation],
              let topResult = results.first else {
            fatalError("Failed to get results from ResNet50 model.")
        }

        if topResult.identifier == "object" {
            resnetCorrectCount += 1
        }
    }

    let startTime = CACurrentMediaTime()
    let handler = VNImageRequestHandler(cgImage: image)
    try? handler.perform([request])
    let endTime = CACurrentMediaTime()

    resnetTotalTime += endTime - startTime
}
let resnetAccuracy = Double(resnetCorrectCount) / Double(images.count)
let resnetAverageTime = resnetTotalTime / Double(images.count)
print("ResNet50 accuracy: \(resnetAccuracy)")
print("ResNet50 average inference time: \(resnetAverageTime) seconds")
// Run inference on the VGG16 model
var vggTotalTime: Double = 0
var vggCorrectCount = 0
for image in images {
    let request = VNCoreMLRequest(model: vggModel) { (request, error) in
        guard let results = request.results as? [VNClassificationObservation],
              let topResult = results.first else {
            fatalError("Failed to get results from VGG16 model.")
        }

        if topResult.identifier == "object" {
            vggCorrectCount += 1
        }
    }

    let startTime = CACurrentMediaTime()
    let handler = VNImageRequestHandler(cgImage: image)
    try? handler.perform([request])
    let endTime = CACurrentMediaTime()

    vggTotalTime += endTime - startTime
}
let vggAccuracy = Double(vggCorrectCount) / Double(images.count)
let vggAverageTime = vggTotalTime / Double(images.count)
print("VGG16 accuracy: \(vggAccuracy)")
print("VGG16 average inference time: \(vggAverageTime) seconds")
```
Note that this code assumes that the ResNet50 and VGG16 models are available as Core ML models in your project. If they are not, you will need to convert them to Core ML format using the `coremltools` Python package.

