#include <iostream>
#include <string>
using namespace std;
// Function to calculate the checksum digit
int calculateChecksum(string upc)
{
    int sumOdd = 0;
    int sumEven = 0;
    for (int i = 0; i < upc.length(); i++)
    {
        if (i % 2 == 0)
        {
            sumOdd += upc[i] - '0';
        }
        else
        {
            sumEven += upc[i] - '0';
        }
    }
    int total = (sumOdd * 3) + sumEven;
    int checksum = 10 - (total % 10);
    if (checksum == 10)
    {
        checksum = 0;
    }
    return checksum;
}
int main()
{
    string manufacturerCode;
    string productCode;
    cout << "Enter the manufacturer code (6 digits): ";
    cin >> manufacturerCode;
    cout << "Enter the product code (5 digits): ";
    cin >> productCode;
    string upc = "0" + manufacturerCode + productCode;
    // Calculate the checksum digit
