Suppose you have a group of people who all speak different languages. You want to create a code that can translate any word from one language to another using WordNet and Python NLTK. Your goal is to retrieve the top 3 most commonly associated adjectives for a specific word and translate them into the target language. 
Here's the Python code to achieve this:
```python
from nltk.corpus import wordnet as wn
from nltk.corpus import wordnet_ic
from nltk import pos_tag, word_tokenize
import requests
def translate_word(word, source_language, target_language):
    synonyms = []
    for synset in wn.synsets(word):
        for lemma in synset.lemmas():
            synonyms.append(lemma.name())
    synonyms = list(set(synonyms))
    adjectives = []
    for syn in synonyms:
        for s in wn.synsets(syn):
            for l in s.lemmas():
                if l.antonyms():
                    for a in l.antonyms():
                        if a.name() not in adjectives and a.synset().pos() == 'a':
                            adjectives.append(a.name())
                elif l.name() not in adjectives and l.synset().pos() == 'a':
                    adjectives.append(l.name())
    adjectives = sorted(adjectives, key=lambda x: wn.synset(x + '.' + 'a.01').pos_score(), reverse=True)[:3]
    translated_words = []
    for adj in adjectives:
        url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl={}&tl={}&dt=t&q={}".format(source_language, target_language, adj)
        r = requests.get(url)
        if r.status_code == 200:
            translation = r.json()[0][0][0]
            translated_words.append(translation)
    return translated_words
```
Can you explain how this code works and how it retrieves the top 3 most commonly associated adjectives for a specific word?

