Here's a C program that implements a queue data structure using function pointers:
```c
#include <stdio.h>
#include <stdlib.h>
#define MAX_QUEUE_SIZE 100
typedef struct {
    int data[MAX_QUEUE_SIZE];
    int front;
    int rear;
} Queue;
void enqueue(Queue *q, int x);
int dequeue(Queue *q);
void display(Queue *q);
int main() {
    Queue q = {{0}, -1, -1};
    int choice, x;
    void (*enqueue_ptr)(Queue *, int) = &enqueue;
    int (*dequeue_ptr)(Queue *) = &dequeue;
    while (1) {
        printf("\nQueue Operations:\n");
        printf("1. Enqueue\n");
        printf("2. Dequeue\n");
        printf("3. Display\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);
        switch (choice) {
            case 1:
                printf("Enter the element to be enqueued: ");
                scanf("%d", &x);
                enqueue_ptr(&q, x);
                break;
            case 2:
                x = dequeue_ptr(&q);
                if (x != -1) {
                    printf("Dequeued element: %d\n", x);
                }
                break;
            case 3:
                display(&q);
                break;
            case 4:
                exit(0);
                break;
            default:
                printf("Invalid choice!\n");
                break;
        }
    }
    return 0;
}
void enqueue(Queue *q, int x) {
    if (q->rear == MAX_QUEUE_SIZE - 1) {
        printf("Queue overflow!\n");
        return;
    }
    if (q->front == -1) {
        q->front = 0;
    }
    q->rear++;
    q->data[q->rear] = x;
}
int dequeue(Queue *q) {
    if (q->front == -1 || q->front > q->rear) {
        printf("Queue underflow!\n");
        return -1;
    }
    int x = q->data[q->front];
    q->front++;
    if (q->front > q->rear) {
        q->front = -1;
        q->rear = -1;
    }
    return x;
}
void display(Queue *q) {
    if (q->front == -1) {
        printf("Queue is empty!\n");
        return;
    }
    printf("Queue elements: ");
    for (int i = q->front; i <= q->rear; i++) {
        printf("%d ", q->data[i]);
    }
    printf("\n");
}
```
In this program, we define a `Queue` struct that contains an array of integers, and two pointers - `front` and `rear` - that keep track of the front and rear of the queue.
