```swift
func mergeSort<T: Comparable>(_ array: [T]) -> [T] {
    guard array.count > 1 else {
        return array
    }
    let middleIndex = array.count / 2
    let leftArray = mergeSort(Array(array[..<middleIndex]))
    let rightArray = mergeSort(Array(array[middleIndex...]))
    return merge(leftArray, rightArray)
}
func merge<T: Comparable>(_ leftArray: [T], _ rightArray: [T]) -> [T] {
    var leftIndex = 0
    var rightIndex = 0
    var resultArray = [T]()
    while leftIndex < leftArray.count && rightIndex < rightArray.count {
        let leftElement = leftArray[leftIndex]
        let rightElement = rightArray[rightIndex]
        if leftElement < rightElement {
            resultArray.append(leftElement)
            leftIndex += 1
        } else if leftElement > rightElement {
            resultArray.append(rightElement)
            rightIndex += 1
        } else {
            resultArray.append(leftElement)
            leftIndex += 1
            resultArray.append(rightElement)
            rightIndex += 1
        }
    }
    while leftIndex < leftArray.count {
        resultArray.append(leftArray[leftIndex])
        leftIndex += 1
    }
    while rightIndex < rightArray.count {
        resultArray.append(rightArray[rightIndex])
        rightIndex += 1
    }
    return resultArray
}
let numbers = [3, 8, 5, 1, 9]
let sortedNumbers = mergeSort(numbers)
print(sortedNumbers)
```
