    private T[] stack;
    private int top;
    @SuppressWarnings("unchecked")
    public MyStack(int size) {
        stack = (T[]) new Object[size];
        top = -1;
    }
    public void push(T element) {
        if (top == stack.length - 1) {
            throw new StackOverflowError();
        }
        stack[++top] = element;
    }
